(()=>{
'use strict';
if(window.__gtavAdminAdditionalModsV1)return;window.__gtavAdminAdditionalModsV1=true;
const API='/api/additional-mods',TOKEN_KEY='gtav-admin-token-v2';
const token=()=>sessionStorage.getItem(TOKEN_KEY)||'';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let items=[],editing='';
async function req(url,options={}){const r=await fetch(url,{cache:'no-store',...options});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'request_failed');return d}
function headers(){return{'Content-Type':'application/json','X-Admin-Token':token(),'Accept':'application/json'}}
function style(){if(document.getElementById('admin-additional-mods-style'))return;const s=document.createElement('style');s.id='admin-additional-mods-style';s.textContent=`.additional-admin-card{grid-column:1/-1}.additional-admin-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:14px}.additional-admin-head h2{margin:0 0 4px}.additional-admin-head small{color:var(--muted,#888)}.additional-admin-form{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr) auto;gap:9px;align-items:end}.additional-admin-form .field{min-width:0}.additional-admin-form .button{min-height:43px;white-space:nowrap}.additional-admin-status{display:block;min-height:18px;margin-top:9px;font-size:.68rem;color:var(--muted,#888)}.additional-admin-status.ok{color:#62d78c}.additional-admin-status.error{color:#ff7474}.additional-admin-list{display:grid;gap:7px;margin-top:15px;border-top:1px solid color-mix(in srgb,currentColor 8%,transparent);padding-top:12px}.additional-admin-item{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center;padding:9px 0;border-bottom:1px solid color-mix(in srgb,currentColor 6%,transparent)}.additional-admin-item:last-child{border-bottom:0}.additional-admin-copy{min-width:0}.additional-admin-copy strong{display:block;font-size:.78rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.additional-admin-copy small{display:block;margin-top:3px;color:var(--muted,#777);font-size:.61rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.additional-admin-actions{display:flex;gap:5px}.additional-admin-actions button{appearance:none;border:1px solid color-mix(in srgb,currentColor 10%,transparent);background:transparent;color:inherit;border-radius:8px;padding:7px 9px;font:800 .6rem/1 inherit}.additional-admin-actions .delete{color:#ff7474}@media(max-width:700px){.additional-admin-form{grid-template-columns:1fr}.additional-admin-form .button{width:100%}.additional-admin-head{align-items:flex-start;flex-direction:column}.additional-admin-item{grid-template-columns:1fr}.additional-admin-actions{display:grid;grid-template-columns:1fr 1fr}.additional-admin-actions button{min-height:38px}}`;document.head.append(s)}
function setStatus(text,type=''){const el=document.getElementById('additional-status');if(!el)return;el.textContent=text;el.className='additional-admin-status'+(type?' '+type:'')}
function render(){const root=document.getElementById('additional-list');if(!root)return;root.replaceChildren();if(!items.length){root.innerHTML='<div class="mods-admin-empty">No Additional Mods yet.</div>';return}items.forEach(item=>{const row=document.createElement('div');row.className='additional-admin-item';row.innerHTML=`<div class="additional-admin-copy"><strong>${esc(item.title)}</strong><small>${esc(item.downloadUrl)}</small></div><div class="additional-admin-actions"><button type="button" data-edit="${esc(item.id)}">Edit</button><button type="button" class="delete" data-delete="${esc(item.id)}">Delete</button></div>`;root.append(row)});root.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>edit(b.dataset.edit)));root.querySelectorAll('[data-delete]').forEach(b=>b.addEventListener('click',()=>remove(b.dataset.delete)))}
async function load(){if(!token())return;try{const data=await req(API+'?admin=1',{headers:headers()});items=Array.isArray(data.mods)?data.mods:[];render()}catch{setStatus('Could not load Additional Mods.','error')}}
function reset(){editing='';document.getElementById('additional-title').value='';document.getElementById('additional-link').value='';document.getElementById('additional-submit').textContent='Add mod';setStatus('Ready.')}
function edit(id){const item=items.find(x=>x.id===id);if(!item)return;editing=id;document.getElementById('additional-title').value=item.title||'';document.getElementById('additional-link').value=item.downloadUrl||'';document.getElementById('additional-submit').textContent='Save';setStatus('Editing '+item.title);document.getElementById('additional-title').focus()}
async function remove(id){const item=items.find(x=>x.id===id);if(!item||!confirm(`Delete “${item.title}”?`))return;try{await req(`${API}?id=${encodeURIComponent(id)}`,{method:'DELETE',headers:headers()});if(editing===id)reset();await load()}catch{setStatus('Could not delete this mod.','error')}}
async function save(e){e.preventDefault();const title=document.getElementById('additional-title').value.trim(),downloadUrl=document.getElementById('additional-link').value.trim();if(!title||!downloadUrl){setStatus('Title and download link are required.','error');return}const button=document.getElementById('additional-submit');button.disabled=true;setStatus(editing?'Saving…':'Adding…');try{await req(editing?`${API}?id=${encodeURIComponent(editing)}`:API,{method:editing?'PUT':'POST',headers:headers(),body:JSON.stringify({title,downloadUrl,published:true,sortOrder:100})});setStatus(editing?'Saved.':'Added to Additional Mods.','ok');editing='';document.getElementById('additional-title').value='';document.getElementById('additional-link').value='';button.textContent='Add mod';await load()}catch(error){setStatus(error.message==='download_url_required'?'Enter a valid HTTPS download link.':'Could not save this mod.','error')}finally{button.disabled=false}}
function mount(){const grid=document.querySelector('#panel-mods .mods-admin-grid');if(!grid||document.getElementById('additional-admin-card'))return false;style();const card=document.createElement('section');card.className='card additional-admin-card';card.id='additional-admin-card';card.innerHTML=`<div class="additional-admin-head"><div><h2>Additional Mods</h2><small>Quick entries. Only a title and download link are needed.</small></div><span class="pill">DROPDOWN COLLECTION</span></div><form id="additional-form" class="additional-admin-form"><div class="field"><label for="additional-title">Mod title *</label><input id="additional-title" maxlength="140" required placeholder="Mod title"></div><div class="field"><label for="additional-link">Download link *</label><input id="additional-link" type="url" required placeholder="https://gofile.io/d/..."></div><button class="button compact" id="additional-submit" type="submit">Add mod</button></form><span id="additional-status" class="additional-admin-status">Ready.</span><div id="additional-list" class="additional-admin-list"><div class="mods-admin-empty">Loading…</div></div>`;grid.prepend(card);document.getElementById('additional-form').addEventListener('submit',save);window.addEventListener('project-admin-unlocked',load);window.addEventListener('project-admin-refreshed',load);document.getElementById('refresh-all')?.addEventListener('click',load);if(token()&&!document.getElementById('dashboard')?.hidden)load();return true}
function start(){if(mount())return;const o=new MutationObserver(()=>{if(mount())o.disconnect()});o.observe(document.body,{childList:true,subtree:true})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
